        for j in range(m):
            if j != i:
                factor = augmented_matrix[j][i]
                for k in range(n*2):
                    augmented_matrix[j][k] -= factor * augmented_matrix[i][k]

    inverse = [row[n:] for row in augmented_matrix]
    return inverse

def matrix_determinant(A):
