        return A[0][0]

    det = Fraction(0, 1)
    for j in range(m):
        submatrix = [row[:j] + row[j+1:] for row in A[1:]]
        det += ((-1) ** j) * A[0][j] * matrix_determinant(submatrix)

    return det

